"""Project EVOLVE read-only dashboard. Run: python evolve_dashboard.py"""
import sqlite3, json, html, os
from pathlib import Path
from datetime import datetime, timezone

source=Path(os.getenv('EVOLVE_DB','state/evolve.sqlite3'))
out=Path(os.getenv('EVOLVE_DASHBOARD','dashboard.html'))
if not source.is_file():
    raise SystemExit(f'Missing database: {source}. Run this after restoring the saved database.')
db=sqlite3.connect(f'file:{source.resolve()}?mode=ro',uri=True)
db.row_factory=sqlite3.Row
get=lambda sql:[dict(x) for x in db.execute(sql)]
bots=get('SELECT * FROM bots ORDER BY id')
trades=get('SELECT * FROM trades ORDER BY time DESC,id DESC LIMIT 200')
events=get('SELECT * FROM events ORDER BY time DESC,id DESC LIMIT 100')
latest=db.execute('SELECT time,close FROM candles ORDER BY time DESC LIMIT 1').fetchone()
price=float(latest['close']) if latest else None
for b in bots:
    b['equity']=round(b['cash']+b['sol']*price,6) if price is not None else None
    b['unrealized']=round(b['sol']*price-(b['entry'] or 0),6) if price is not None and b['sol']>0 else (0 if price is not None else None)
    b['win_rate']=round(100*b['wins']/b['closed_trades'],2) if b['closed_trades'] else None
payload={'bots':bots,'trades':trades,'events':events,'price':price,'price_time':latest['time'] if latest else None,'generated':datetime.now(timezone.utc).isoformat()}
db.close()
data=json.dumps(payload).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
page='''<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Project EVOLVE Dashboard</title><style>
:root{font-family:system-ui,sans-serif;color-scheme:dark;background:#0b1020;color:#f1f5ff}*{box-sizing:border-box}body{margin:auto;max-width:1100px;padding:22px 14px 50px}h1{margin:5px 0;font-size:1.8rem}h2{font-size:1.1rem;margin:0 0 14px}.muted{color:#9caec9;font-size:.85rem}.brand{color:#7dd3fc;font-size:.75rem;letter-spacing:.13em;font-weight:800}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(145px,1fr));gap:12px;margin:20px 0}.bots{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:12px}.card,.panel{background:#151e32;border:1px solid #2a3955;border-radius:16px;padding:17px}.panel{margin-top:16px}.value{font-size:1.55rem;font-weight:800;margin-top:8px}.positive{color:#4ade80}.negative{color:#fb7185}.pill{border:1px solid #496084;border-radius:30px;padding:4px 9px;font-size:.73rem;color:#b6d7ff}.head{display:flex;justify-content:space-between;align-items:center;gap:8px}.stats{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:15px}.stat{font-size:.88rem}.stat strong{display:block;font-size:1rem;margin-top:3px}.notice{padding:12px;background:#142b3e;border-left:3px solid #38bdf8;border-radius:8px;margin:18px 0;font-size:.85rem}.scroll{overflow:auto;max-height:430px}table{border-collapse:collapse;width:100%;font-size:.8rem}th,td{text-align:left;white-space:nowrap;padding:11px 10px;border-bottom:1px solid #2b3a53}th{color:#a5b4fc;position:sticky;top:0;background:#151e32}button{background:#273b5c;border:1px solid #496084;color:white;border-radius:8px;padding:9px}footer{font-size:.78rem;color:#9caec9;margin-top:24px}</style></head><body>
<div class="brand">PROJECT EVOLVE · PAPER TRADING</div><h1>Bot Command Center 🧬</h1><div class="muted" id="stamp"></div><div class="notice">Read-only database snapshot. Values are virtual USD, not real money. Refresh by generating a new snapshot after a trading run.</div><div class="grid" id="overview"></div><section class="panel"><h2>Bot performance</h2><div class="bots" id="bots"></div></section><section class="panel"><h2>Recent paper trades</h2><div class="scroll" id="trades"></div></section><section class="panel"><h2>Evolution events</h2><div class="scroll" id="events"></div></section><footer>Prices and balances are from the saved SQLite database. P/L is not a prediction of future performance.</footer>
<script>const D=__DATA__;const esc=x=>String(x??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const money=x=>x==null?'—':'$'+Number(x).toFixed(2);const n=x=>x==null?'—':Number(x).toFixed(2);const dt=x=>x==null?'—':new Date(Number(x)*1000).toLocaleString();const sum=xs=>xs.reduce((a,b)=>a+b,0);const equity=D.bots.every(b=>b.equity!=null)?sum(D.bots.map(b=>b.equity)):null;const start=30;const delta=equity==null?null:equity-start;document.getElementById('stamp').textContent='Snapshot generated: '+new Date(D.generated).toLocaleString()+' · Last candle: '+dt(D.price_time);const items=[['Total equity',money(equity)],['Change vs original $30',delta==null?'—':money(delta)],['SOL last recorded',money(D.price)],['Active bots',D.bots.filter(b=>b.active).length+' / '+D.bots.length],['Closed trades',sum(D.bots.map(b=>b.closed_trades))],['Recorded trades',D.trades.length+(D.trades.length===200?'+':'')]];document.getElementById('overview').innerHTML=items.map(([k,v])=>`<div class="card"><div class="muted">${esc(k)}</div><div class="value">${esc(v)}</div></div>`).join('');document.getElementById('bots').innerHTML=D.bots.map(b=>`<article class="card"><div class="head"><strong>Bot #${b.id} · ${esc(b.strategy)}</strong><span class="pill">${b.active?'Active':'Inactive'}</span></div><div class="muted" style="margin-top:14px">Virtual equity</div><div class="value">${money(b.equity)}</div><div class="stats"><div class="stat muted">Cash<strong>${money(b.cash)}</strong></div><div class="stat muted">SOL held<strong>${n(b.sol)}</strong></div><div class="stat muted">Realized P/L<strong>${money(b.realized)}</strong></div><div class="stat muted">Open-position P/L<strong>${money(b.unrealized)}</strong></div><div class="stat muted">Closed trades<strong>${b.closed_trades}</strong></div><div class="stat muted">Win rate<strong>${b.win_rate==null?'—':b.win_rate+'%'}</strong></div><div class="stat muted">Generation<strong>${b.generation}</strong></div><div class="stat muted">Parent bot<strong>${b.parent??'Original'}</strong></div></div></article>`).join('')||'<p>No bots recorded.</p>';const tbl=(rows,cols)=>rows.length?`<table><thead><tr>${cols.map(([k,l])=>`<th>${esc(l)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${cols.map(([k,l,f])=>`<td>${esc(f?f(r[k]):r[k])}</td>`).join('')}</tr>`).join('')}</tbody></table>`:'<p class="muted">No records yet.</p>';document.getElementById('trades').innerHTML=tbl(D.trades,[['time','Time',dt],['bot_id','Bot'],['side','Side'],['price','Price',money],['quantity','SOL',n],['fee','Fee',money],['pnl','Realized P/L',money]]);document.getElementById('events').innerHTML=tbl(D.events,[['time','Time',dt],['event','Event']]);</script></body></html>'''
out.write_text(page.replace('__DATA__',data),encoding='utf-8')
print('Dashboard generated:',out)
